// Worker entry point. OpenNext builds the Next.js app into .open-next/worker.js; this file wraps
// it so that /api/** is answered by our own handlers (and the room Durable Objects) and every
// response leaves with the security headers.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "./.open-next/worker.js"
import { handleApiRequest } from "./src/server/api"
import type { Env } from "./src/server/env"
import { withSecurityHeaders } from "./src/server/security"

export { RoomDO } from "./src/server/room-do"

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url)

    if (url.pathname.startsWith("/api/")) {
      try {
        const response = await handleApiRequest(request, env)
        // A WebSocket handshake (101) must be returned untouched.
        if (response.status === 101) return response
        return withSecurityHeaders(response, { isApi: true })
      } catch (error) {
        console.error("api error", { path: url.pathname, error: String(error) })
        return withSecurityHeaders(Response.json({ error: "internal" }, { status: 500 }), {
          isApi: true,
        })
      }
    }

    const response: Response = await nextHandler.fetch(request, env, ctx)
    return withSecurityHeaders(response, { isApi: false })
  },
} satisfies ExportedHandler<Env>
